return [
  { json: { member_id: 'M1001' } },
  { json: { member_id: 'M1003' } },
  { json: { member_id: 'M9999' } }
];

const definitions = {
  M1001: {
    test_id: 'ELIG-001',
    expected: {
      status: 'SUCCESS',
      coverage_status: 'ACTIVE',
      enrollment_status: 'ACTIVE'
    }
  },
  M1003: {
    test_id: 'ELIG-002',
    expected: {
      status: 'SUCCESS',
      coverage_status: 'INACTIVE',
      enrollment_status: 'ACTIVE'
    }
  },
  M9999: {
    test_id: 'ELIG-003',
    expected: { status: 'NOT_FOUND' }
  }
};

return $input.all().map((item) => {
  const actual = item.json ?? {};
  const definition = definitions[actual.member_id];
  const failures = [];

  if (!definition) {
    failures.push('Unexpected member_id returned');
  } else {
    if (actual.status !== definition.expected.status) {
      failures.push('Expected status ' + definition.expected.status + ', received ' + actual.status);
    }
    if (definition.expected.status === 'SUCCESS') {
      if (actual.data?.coverage_status !== definition.expected.coverage_status) {
        failures.push('Coverage status did not match');
      }
      if (actual.data?.enrollment_status !== definition.expected.enrollment_status) {
        failures.push('Enrollment status did not match');
      }
    }
  }

  return {
    json: {
      test_id: definition?.test_id ?? 'ELIG-UNKNOWN',
      tool: 'ELIGIBILITY',
      passed: failures.length === 0,
      expected: definition?.expected ?? {},
      actual,
      failure_reason: failures.length ? failures.join('; ') : null
    }
  };
});

