    test_id: 'AUTH-001',
    expected: {
      status: 'SUCCESS',
      authorization_id: 'PA8001',
      authorization_status: 'APPROVED',
      provider_id: 'P7001',
      provider_location_id: 'L7101'
    }
  },
  'M1002|MRI-SIM-001|2026-06-10': {
