    expected: { status: 'NOT_FOUND' }
  },
  'M1004|MRI-SIM-001|2026-07-18': {
    test_id: 'AUTH-003',
    expected: {
      status: 'SUCCESS',
      authorization_id: 'PA8004',
      authorization_status: 'APPROVED'
    }
  }
};

return $input.all().map((item) => {
  const actual = item.json ?? {};
  const key = actual.member_id + '|' + actual.service_code + '|' + actual.service_date;
  const definition = definitions[key];
  const failures = [];

  if (!definition) {
    failures.push('Unexpected authorization lookup identifiers returned');
  } else {
    if (actual.status !== definition.expected.status) {
      failures.push('Expected status ' + definition.expected.status + ', received ' + actual.status);
    }
    if (definition.expected.status === 'SUCCESS') {
      if (actual.data?.authorization_id !== definition.expected.authorization_id) {
        failures.push('Authorization ID did not match');
      }
      if (actual.data?.status !== definition.expected.authorization_status) {
