      }
      if (definition.expected.provider_id && actual.data?.provider_id !== definition.expected.provider_id) {
        failures.push('Provider ID did not match');
      }
      if (definition.expected.provider_location_id && actual.data?.provider_location_id !== definition.expected.provider_location_id) {
        failures.push('Provider location ID did not match');
      }
    }
  }

  return {
    json: {
      test_id: definition?.test_id ?? 'AUTH-UNKNOWN',
      tool: 'AUTHORIZATION',
      passed: failures.length === 0,
      expected: definition?.expected ?? {},
      actual,
      failure_reason: failures.length ? failures.join('; ') : null
    }
  };
});

const definitions = {
  P7001: {
    test_id: 'PROV-001',
    expected: {
      status: 'SUCCESS',
      organization_name: 'ABC Imaging',
      location_ids: ['L7101', 'L7102'],
      network_status: 'IN_NETWORK'
    }
  }
};

return $input.all().map((item) => {
  const actual = item.json ?? {};
  const definition = definitions[actual.provider_id];
  const failures = [];

  if (!definition) {
    failures.push('Unexpected provider_id returned');
  } else {
    if (actual.status !== definition.expected.status) {
      failures.push('Expected status SUCCESS, received ' + actual.status);
    }
    if (actual.data?.organization_name !== definition.expected.organization_name) {
      failures.push('Organization name did not match');
    }
    const locations = Array.isArray(actual.data?.locations) ? actual.data.locations : [];
    for (const locationId of definition.expected.location_ids) {
      const location = locations.find((record) => record.provider_location_id === locationId);
      if (!location) {
        failures.push('Location ' + locationId + ' was not returned');
      } else if (location.network_status !== definition.expected.network_status) {
        failures.push('Location ' + locationId + ' was not in network');
      }
    }
  }

  return {
    json: {
      test_id: definition?.test_id ?? 'PROV-UNKNOWN',
      tool: 'PROVIDER',
      passed: failures.length === 0,
      expected: definition?.expected ?? {},
      actual,
      failure_reason: failures.length ? failures.join('; ') : null
    }
  };
});

const results = $input.all().map((item) => item.json);
const expectedCounts = {
  ELIGIBILITY: 3,
  BENEFITS: 2,
  CLAIMS: 1,
  AUTHORIZATION: 3,
  PROVIDER: 1
};
const byTool = {};

for (const [tool, expectedCount] of Object.entries(expectedCounts)) {
  const toolResults = results.filter((result) => result.tool === tool);
  const passed = toolResults.filter((result) => result.passed === true).length;
  const explicitFailures = toolResults.filter((result) => result.passed !== true).length;
  const missing = Math.max(0, expectedCount - toolResults.length);
  byTool[tool] = {
    passed,
    failed: explicitFailures + missing
  };
}

const expectedTotal = Object.values(expectedCounts).reduce((sum, count) => sum + count, 0);
const passed = results.filter((result) => result.passed === true).length;
const explicitFailures = results.filter((result) => result.passed !== true).length;
const missing = Math.max(0, expectedTotal - results.length);
const failed = explicitFailures + missing;

return [
  {
    json: {
      suite: 'OneCall AI Domain Tools',
      status: results.length === expectedTotal && failed === 0 ? 'PASS' : 'FAIL',
      total: expectedTotal,
      passed,
      failed,
      by_tool: byTool,
      results
    }
  }
];
